/* ---------- 13c. economy — diamonds, challenges, shop, profile ---------- */
/* One currency (diamonds) feeds one shop, and both are earned by the same
   challenge/achievement engine, so the loop closes:

      play -> merges/score -> achievements + daily/weekly challenges
           -> diamonds -> shop (bomb / sweep / freeze) -> easier play

   Everything here runs fully offline against localStorage. `Net` is the only
   seam that talks to a server, so plugging in Supabase later changes the
   transport and nothing else. */

/* ============================================================ Net seam === */
/* Leave NET_CONFIG empty and the game is a self-contained offline build with
   a local profile and a local leaderboard. Fill it in (Supabase URL + anon
   key) and the very same calls hit the server: real Google login, real
   cross-player leaderboard. No game code branches on which one is live. */
var NET_CONFIG={ url:"", key:"" };
function netOn(){ return !!(NET_CONFIG&&NET_CONFIG.url&&NET_CONFIG.key); }

/* ------------------------------------------------------------ auth session --
   NET_CONFIG.key is the ANON key: it identifies the project, not the player.
   Sending it as the Bearer would put every request in the `anon` role, so RLS
   could never tell two players apart and anyone could overwrite anyone else's
   score. The player's own access token must be the Bearer; the anon key only
   ever goes in `apikey`. */
var AUTH_TOK_KEY="fruitmerge.auth";
var authTok="";
function signedIn(){ return !!authTok; }
function netHeaders(){
  return { "apikey":NET_CONFIG.key,
           "Authorization":"Bearer "+(authTok||NET_CONFIG.key),
           "Content-Type":"application/json", "Prefer":"return=minimal" };
}
/* Supabase's implicit OAuth flow redirects back with the token in the hash:
     #access_token=...&expires_in=3600&refresh_token=...&type=signup
   Read it once at boot, persist it, then strip the hash so a reload or a
   shared URL never carries a live credential. */
function captureAuthHash(){
  try{
    var h=(window.location&&window.location.hash)||"";
    if(h.indexOf("access_token=")===-1) return false;
    var q={}, parts=h.replace(/^#/,"").split("&");
    for(var i=0;i<parts.length;i++){
      var kv=parts[i].split("=");
      if(kv[0]) q[kv[0]]=decodeURIComponent(kv[1]||"");
    }
    if(!q.access_token) return false;
    authTok=q.access_token;
    try{ localStorage.setItem(AUTH_TOK_KEY,authTok); }catch(e){}
    store.profile.guest=false;
    if(!store.profile.id) store.profile.id=q.user_id||"";
    save();
    if(window.history&&window.history.replaceState)
      window.history.replaceState(null,"",window.location.pathname+window.location.search);
    /* This mutates state the UI depends on (signedIn, profile.guest), so it has
       to repaint. Boot happens to call refreshEcon() afterwards, but relying on
       that ordering would leave the invitation on screen for anyone signed in
       through a path that does not go through boot. */
    refreshSignIn(); refreshEcon();
    return true;
  }catch(e){ return false; }
}
function loadAuthTok(){
  if(authTok) return;
  try{ authTok=localStorage.getItem(AUTH_TOK_KEY)||""; }catch(e){}
  if(authTok&&store.profile) store.profile.guest=false;
}
function clearAuthTok(){
  authTok="";
  try{ localStorage.removeItem(AUTH_TOK_KEY); }catch(e){}
}
function netFetch(path,opt){
  opt=opt||{};
  opt.headers=Object.assign(netHeaders(),opt.headers||{});
  return fetch(NET_CONFIG.url+path,opt).then(function(r){
    if(!r.ok) throw new Error("net "+r.status);
    return r.json();
  });
}

/* ============================================================ store ======= */
/* Additive: an old save simply arrives without these keys and defaults fill
   in, so nobody who already has a best score loses it. */
function econDefaults(){
  return {
    diamonds:0, earned:0, spent:0,
    inv:{ bomb:0, sweep:0, undo:0, freeze:0 },
    ch:{ daily:null, weekly:null },
    claimed:{},                 // challengeId -> day/week stamp
    dailyFree:"",               // date the free 10 were taken on
    dailyAds:0, dailyAdDate:"", // ads watched today (capped)
    profile:{ name:"", guest:true, id:"", nameChangedAt:0 },
    lbCache:{ at:0, rows:[] }
  };
}
function econInit(){
  loadAuthTok();
  captureAuthHash();
  var d=econDefaults();
  for(var k in d){
    if(store[k]===undefined) store[k]=d[k];
    else if(d[k]&&typeof d[k]==="object"&&!Array.isArray(d[k]))
      store[k]=Object.assign({},d[k],store[k]);
  }
  if(!store.inv) store.inv={bomb:0,sweep:0,undo:0,freeze:0};
  for(var p in d.inv) if(store.inv[p]===undefined) store.inv[p]=0;
  if(!store.profile) store.profile=d.profile;
  /* A guest who has never been named gets one now, at boot, so the home chip,
     the profile popup and any leaderboard row never show a blank. */
  if(!store.profile.name){ store.profile.name=randomGuestName(); save(); }
}

/* ============================================================ dates ======= */
function dayKey(t){
  var d=t?new Date(t):new Date();
  return d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate();
}
/* ISO-ish week key: the weekly challenges must roll over for everybody on the
   same boundary, not on each player's own seven-day anniversary. */
function weekKey(t){
  var d=t?new Date(t):new Date();
  var one=new Date(d.getFullYear(),0,1);
  var wk=Math.ceil((((d-one)/86400000)+one.getDay()+1)/7);
  return d.getFullYear()+"-W"+wk;
}
function daysSince(ts){ return ts? Math.floor((Date.now()-ts)/86400000) : 999; }

/* ============================================================ period roll == */
/* The "best score / best combo" challenges measure a peak INSIDE the current
   week, so those peaks have to be zeroed when the week turns over -- otherwise
   a player carries last week's 9,000 straight into this week's challenge and
   claims it without playing. Called at boot and after any date-sensitive read. */
function rollPeriod(){
  var wk=weekKey();
  if(store.periodKey!==wk){
    store.periodKey=wk; store.periodBest=0; store.periodCombo=0; store.weekBest=0;
    save();
  }
}

/* ============================================================ diamonds ==== */
function addDiamonds(n,why){
  if(!n) return;
  store.diamonds=Math.max(0,store.diamonds+n);
  if(n>0) store.earned+=n; else store.spent+=(-n);
  save(); refreshEcon();
  if(n>0) diaToast("+"+n+" 💎",why);
}
function spendDiamonds(n){
  if(store.diamonds<n) return false;
  store.diamonds-=n; store.spent+=n; save(); refreshEcon(); return true;
}

/* ============================================================ challenges == */
/* Daily and weekly challenges are derived from a seed, not stored as a list of
   random picks: the same day gives every player the same three challenges, and
   re-rolling on every load would let a player fish for an easy one. */
var CH_POOL=[
  {id:"merges",  n:"Merge {0} fruits",       d:20, w:140, r:5,  m:function(){return store.merges;}},
  {id:"melons",  n:"Make {0} watermelons",   d:1,  w:6,   r:10, m:function(){return store.melons;}},
  {id:"score",   n:"Score {0} in one game",  d:1500,w:9000,r:8,  m:function(){return store.best;}},
  {id:"games",   n:"Play {0} games",         d:3,  w:15,  r:6,  m:function(){return store.games;}},
  {id:"combo",   n:"Reach a x{0} combo",     d:3,  w:6,   r:8,  m:function(){return store.bestCombo||0;}},
  {id:"powers",  n:"Use {0} powers",         d:3,  w:18,  r:5,  m:function(){var p=store.powersUsed;return p.s+p.u+p.f;}},
  {id:"drops",   n:"Drop {0} fruits",        d:25, w:180, r:5,  m:function(){return store.totalDrops||0;}}
];
/* Which counters the pool reads, so a challenge can be measured as "since the
   period started" rather than "since the account was created". */
function chBaselineSnapshot(){
  return { merges:store.merges, melons:store.melons, games:store.games,
           powers:(store.powersUsed.s+store.powersUsed.u+store.powersUsed.f),
           drops:store.totalDrops||0, best:0, combo:0 };
}
function pickChallenges(kind){
  var key = kind==="daily"? dayKey() : weekKey();
  var have = store.ch[kind];
  if(have&&have.key===key) return have;
  /* Deterministic pick: seed from the key so the whole world agrees, and so a
     reload cannot re-roll the list. */
  var seed=0; for(var i=0;i<key.length;i++) seed=(seed*31+key.charCodeAt(i))>>>0;
  var rnd=mulberry32(seed);
  var n = kind==="daily"? 3 : 6;
  var pool=CH_POOL.slice();
  for(var j=pool.length-1;j>0;j--){ var k=Math.floor(rnd()*(j+1)); var t=pool[j]; pool[j]=pool[k]; pool[k]=t; }
  var list=[];
  for(var q=0;q<n&&q<pool.length;q++){
    var c=pool[q];
    list.push({ id:c.id, target: kind==="daily"? c.d : c.w, reward: kind==="daily"? c.r : Math.round(c.r*2.5),
                text: c.n.replace("{0}", kind==="daily"? c.d : c.w) });
  }
  store.ch[kind]={ key:key, list:list, base:chBaselineSnapshot() };
  save();
  return store.ch[kind];
}
function chProgress(kind,c){
  var ch=store.ch[kind]; if(!ch) return 0;
  var def=null; for(var i=0;i<CH_POOL.length;i++) if(CH_POOL[i].id===c.id) def=CH_POOL[i];
  if(!def) return 0;
  var base=ch.base||{};
  /* score and combo are "best inside the period", so they read the live peak
     rather than a delta; the rest are counters that must be differenced or a
     player would start the day already finished. */
  if(c.id==="score") return Math.max(0,(store.periodBest||0));
  if(c.id==="combo") return Math.max(0,(store.periodCombo||0));
  var now=def.m();
  return Math.max(0, now-(base[def.id]||0));
}
function chClaimed(kind,c){
  var ch=store.ch[kind]; if(!ch) return false;
  return store.claimed[c.id+"@"+ch.key]===true;
}
function claimChallenge(kind,c){
  if(chClaimed(kind,c)) return false;
  if(chProgress(kind,c)<c.target) return false;
  store.claimed[c.id+"@"+store.ch[kind].key]=true;
  save();
  addDiamonds(c.reward, c.text);
  sfxUnlock(); buzz([20,20,20]);
  return true;
}

/* ============================================================ daily free == */
var DAILY_FREE=10, AD_DIAMONDS=50, AD_DAILY_CAP=5;
function dailyFreeAvailable(){ return store.dailyFree!==dayKey(); }
function takeDailyFree(){
  if(!dailyFreeAvailable()) return false;
  store.dailyFree=dayKey(); save();
  addDiamonds(DAILY_FREE,"Daily bonus");
  return true;
}
function adsLeftToday(){
  if(store.dailyAdDate!==dayKey()){ store.dailyAds=0; store.dailyAdDate=dayKey(); save(); }
  return Math.max(0,AD_DAILY_CAP-store.dailyAds);
}
function grantAdDiamonds(){
  if(adsLeftToday()<=0) return false;
  store.dailyAds++; save();
  addDiamonds(AD_DIAMONDS,"Ad reward");
  return true;
}

/* ============================================================ shop ======== */
var SHOP=[
  {id:"bomb",   n:"Bomb fruit",  ico:"💣", price:60,  desc:"Blasts its neighbours on contact"},
  {id:"sweep",  n:"Sweep",       ico:"🧹", price:40,  desc:"Clears the 3 oldest fruits"},
  {id:"undo",   n:"Undo",        ico:"↩",  price:30,  desc:"Take back your last drop"},
  {id:"freeze", n:"Freeze",      ico:"❄",  price:45,  desc:"Hold everything still for 6s"}
];
/* Demo price list for the "buy diamonds" screen. Deliberately inert: it shows
   what a real IAP tier would look like without wiring up billing. */
var DIAMOND_PACKS=[
  {id:"p1", amt:100,  price:"$0.99",  bonus:0},
  {id:"p2", amt:550,  price:"$4.99",  bonus:10},
  {id:"p3", amt:1200, price:"$9.99",  bonus:20},
  {id:"p4", amt:6500, price:"$49.99", bonus:30}
];
function buyItem(id){
  var it=null; for(var i=0;i<SHOP.length;i++) if(SHOP[i].id===id) it=SHOP[i];
  if(!it) return false;
  if(!spendDiamonds(it.price)) return false;
  /* ALL purchases go to store.inv, which is persistent. An earlier version
     wrote sweep/undo/freeze straight into `powers`, but newRound() resets that
     object every round -- so a player paid 40 diamonds, pressed PLAY, and the
     purchase silently vanished. store.inv survives rounds; `powers` is only
     the free per-round allotment. */
  if(!store.inv[id]) store.inv[id]=0;
  store.inv[id]++;
  save(); updatePowerUI(); refreshEcon();
  sfxUnlock(); buzz([15,15]);
  diaToast(it.ico+" "+it.n,"Purchased");
  return true;
}

/* ============================================================ profile ===== */
var NAME_MIN=2, NAME_MAX=16, NAME_COOLDOWN_DAYS=7;
/* Guests get a fun name at first boot instead of a bare "Player", so the home
   chip and the leaderboard always show something with a little character.
   The name is still changeable -- but only once the player signs in. */
var GUEST_NAMES=["Mango Master","Berry Boss","Melon King","Peach Pro","Cherry Champ",
  "Guava Guru","Apple Ace","Lemon Legend","Jam Jet","Fruit Fox","Sweet Tooth","Orchard Owl"];
function randomGuestName(){
  return GUEST_NAMES[Math.floor(Math.random()*GUEST_NAMES.length)]
    +" "+Math.floor(10+Math.random()*90);
}
/* Fruit faces for the avatar picker. Pure emoji so it works offline and for
   guests and signed-in players alike. */
var AVATARS=["🍉","🥭","","🍊","","🍇","🍍","🥝","","🍋","","🍐","","🫐","🍈"];
function profileAvatar(){ return store.profile.avatar || "🍉"; }
function profileName(){
  return store.profile.name || (store.profile.guest? "Player" : "Player");
}
function canRename(){ return daysSince(store.profile.nameChangedAt)>=NAME_COOLDOWN_DAYS; }
function renameDaysLeft(){ return Math.max(0,NAME_COOLDOWN_DAYS-daysSince(store.profile.nameChangedAt)); }
function setName(raw){
  /* Reject rather than truncate: silently cutting "ThisNameIsFarTooLongForThe
     Field" down to 16 characters hands the player a name they never chose and
     gives them no way to tell it happened. Cooldown is checked LAST so a player
     fixing a typo today is told about the typo, not the calendar. */
  var n=(raw||"").replace(/[<>&"']/g,"").trim();
  /* Changing the name is a signed-in privilege: guests keep the name they were
     dealt until they sign in, which is exactly what the home nudge promises. */
  if(!signedIn()) return {ok:false,why:"login"};
  if(n.length<NAME_MIN) return {ok:false,why:"tooShort"};
  if(n.length>NAME_MAX) return {ok:false,why:"tooLong",max:NAME_MAX};
  if(!canRename()) return {ok:false,why:"cooldown",days:renameDaysLeft()};
  store.profile.name=n;
  store.profile.nameChangedAt=Date.now();
  save(); refreshEcon(); Net.pushProfile();
  return {ok:true,name:n};
}
/* Guest login: no server, no account, still a real profile so the diamond
   balance and challenges persist. A real Google sign-in replaces this via Net. */
function guestLogin(name){
  store.profile.guest=true;
  store.profile.id="guest-"+(store.profile.id||Math.random().toString(36).slice(2,10));
  if(name){ var r=setName(name); if(!r.ok&&r.why==="cooldown") store.profile.name=name, save(); }
  else if(!store.profile.name){
    store.profile.name="Player "+Math.floor(1000+Math.random()*9000);
    save();
  }
  refreshEcon();
  return store.profile;
}
function logout(){
  /* Logging out ends the session; it does not erase the person. The old code
     wiped the name back to a blank default, which is exactly the "name reset"
     the user flagged as a bug -- so the identity (name + face) now survives. */
  clearAuthTok();
  store.profile.guest=true;
  save(); refreshEcon();
}

/* ============================================================ leaderboard = */
/* Three boards, one shape. `rows` is always {name,score,me} so the UI never
   needs to know whether it came from the server or from local play. */
var LB_PAGE=20, LB_MAX=500;
function lbKey(which){ return which; }
function localRows(which){
  /* Offline board: the player's own scores, so the UI is fully exercisable
     without a server. Honest about itself -- the panel says "local". */
  var out=[];
  var best=store.best||0;
  var d=store.dailyBest&&store.dailyBest.d===dayKey()? store.dailyBest.s : 0;
  out.push({name:profileName(),score:which==="daily"? d : best, me:true});
  return out.filter(function(r){return r.score>0;});
}
function lbFetch(which,cb){
  if(!netOn()){ cb(localRows(which)); return; }
  var col = which==="daily"? "score_day" : (which==="weekly"? "score_week" : "score_all");
  /* The daily/weekly boards must only show the CURRENT period. The counters are
     never zeroed on the server (a cron job would be another thing to fail
     silently), so each row carries the period it was set in and we filter on
     it. Without this, last Tuesday's score sits on today's board forever. */
  var filt = which==="daily"?  "&day_key=eq."+encodeURIComponent(dayKey())
           : which==="weekly"? "&week_key=eq."+encodeURIComponent(weekKey())
           : "";
  if(filt) filt += "&"+col+"=gt.0";
  netFetch("/rest/v1/scores?select=name,"+col+"&order="+col+".desc&limit="+LB_MAX+filt)
    .then(function(rows){
      cb(rows.map(function(r){
        return { name:r.name, score:r[col]||0, me:(r.name===profileName()) };
      }));
    })
    .catch(function(){ cb(localRows(which)); });
}
function lbSubmit(){
  /* No token means auth.uid() is null on the server, so the row could never
     satisfy the "own row only" RLS policy. Skip the doomed request instead of
     firing it on every game over. */
  if(!netOn()||!signedIn()) return;
  var body={ name:profileName(), score_all:store.best,
             score_day:(store.dailyBest&&store.dailyBest.d===dayKey())?store.dailyBest.s:0,
             score_week:store.weekBest||0,
             day_key:dayKey(), week_key:weekKey() };
  netFetch("/rest/v1/scores",{ method:"POST",
    headers:{"Prefer":"resolution=merge-duplicates"}, body:JSON.stringify(body) }).catch(function(){});
}

/* ============================================================ Net facade == */
/* Every server touch goes through here. Offline they are no-ops, so the game
   never has to ask "am I online?" at a call site. */
var Net={
  login:function(provider,cb){
    if(!netOn()){ cb(guestLogin()); return; }
    /* Supabase hosted OAuth: redirects back with a token in the hash. */
    if(provider==="google"){
      window.location.href=NET_CONFIG.url+"/auth/v1/authorize?provider=google"+
        "&redirect_to="+encodeURIComponent(window.location.href.split("#")[0]);
      return;
    }
    cb(guestLogin());
  },
  pushScore:function(){ lbSubmit(); },
  /* The name lives on the score row, so pushing the profile is the same
     upsert -- otherwise a rename would not reach the leaderboard until the
     player happened to finish another game. */
  pushProfile:function(){ lbSubmit(); }
};

/* ============================================================ sign-in ===== */
function signInWanted(){
  /* Only invite a Google sign-in when a real auth server is configured.
     With NET_CONFIG empty there is no Google login to perform -- offering the
     button anyway would be a lie, and worse, guestLogin() leaves the profile
     flagged as a guest, so the invitation would reappear on every refreshEcon()
     and nag the player forever. Offline, #netBadge already says "Local save",
     which is the honest message. */
  return netOn() && !signedIn() && !store.siDismissed;
}
function refreshSignIn(){
  var el=document.getElementById("signIn"); if(!el) return;
  el.classList.toggle("hide",!signInWanted());
}
function hideSignIn(){
  var el=document.getElementById("signIn"); if(el) el.classList.add("hide");
}

/* ============================================================ toasts ====== */
function diaToast(big,small){
  var t=document.getElementById("diaToast"); if(!t) return;
  document.getElementById("diaToastBig").textContent=big;
  document.getElementById("diaToastSmall").textContent=small||"";
  t.classList.remove("hide");
  clearTimeout(diaToast._t);
  diaToast._t=setTimeout(function(){ t.classList.add("hide"); },1800);
}

/* ============================================================ rendering == */
function refreshEcon(){
  /* The balance appears on three screens now: the home pill, the Earn panel
     header and the Shop header. They must be DISTINCT ids -- two elements
     sharing one id made getElementById reach only the first, so the panel
     header silently kept showing a stale number. All three are painted. */
  ["diaCount","diaBalCount","shopBal"].forEach(function(id){
    var el=document.getElementById(id);
    if(el) el.textContent=store.diamonds;
  });
  var free=document.getElementById("freeBtn");
  if(free){
    var avail=dailyFreeAvailable();
    free.textContent = avail? T("claimFree") : T("claimed");
    free.classList.toggle("on",avail);
    free.disabled=!avail;
  }
  var ad=document.getElementById("adDiaBtn");
  if(ad){
    var left=adsLeftToday();
    ad.textContent=T("watchAdFor",{0:AD_DIAMONDS,1:left});
    ad.disabled=left<=0;
  }
  var nb=document.getElementById("netBadge");
  if(nb) nb.textContent = netOn()? T("cloudSave") : T("localSave");
  var nb2=document.getElementById("netBadge2");
  if(nb2) nb2.textContent = netOn()? T("cloudSave") : T("localSave");
  refreshSignIn();
  /* The name + face appear in two places: the home chip and the profile popup.
     Paint both from the same source so they can never disagree. */
  ["profName","homeProfName"].forEach(function(id){
    var el=document.getElementById(id); if(el) el.textContent=profileName();
  });
  ["profAvBtn","homeProfAv"].forEach(function(id){
    var el=document.getElementById(id); if(el) el.textContent=profileAvatar();
  });
  /* The bouncing nudge is for guests only; once signed in it has nothing left
     to say. */
  var ng=document.getElementById("loginNudge");
  if(ng) ng.classList.toggle("hide", signedIn());
  var rn=document.getElementById("renameBtn");
  if(rn){
    if(!signedIn()){ rn.disabled=true; rn.textContent="🔒 Login to change name"; }
    else{ rn.disabled=!canRename();
      rn.textContent = canRename()? T("changeName") : T("renameIn",{0:renameDaysLeft()}); }
  }
  buildChallenges(); buildShop();
}
function buildChallenges(){
  var box=document.getElementById("chList"); if(!box) return;
  var html="";
  ["daily","weekly"].forEach(function(kind){
    var ch=pickChallenges(kind);
    html+='<div class="chHead">'+(kind==="daily"?T("dailyCh"):T("weeklyCh"))+
          '<span class="chKey">'+ch.key+'</span></div>';
    ch.list.forEach(function(c){
      var p=Math.min(c.target,chProgress(kind,c));
      var done=p>=c.target, got=chClaimed(kind,c);
      var pct=Math.round(p/c.target*100);
      html+='<div class="chRow'+(got?" got":"")+'">'+
        '<div class="chIco">'+(got?"✅":(done?"🎁":"🎯"))+'</div>'+
        '<div class="chBody"><div class="chText">'+c.text+'</div>'+
        '<div class="chBar"><i style="width:'+pct+'%"></i></div>'+
        '<div class="chMeta">'+p+' / '+c.target+'</div></div>'+
        '<button class="chClaim'+(done&&!got?" ready":"")+'" data-ch="'+kind+'|'+c.id+'"'+
          (got||!done?" disabled":"")+'>'+(got?T("claimed"):"+"+c.reward+" 💎")+'</button></div>';
    });
  });
  box.innerHTML=html;
  var cs=box.querySelectorAll? box.querySelectorAll("[data-ch]") : [];
  for(var i=0;i<cs.length;i++){
    cs[i].addEventListener("click",function(){
      var parts=this.getAttribute("data-ch").split("|");
      var ch=store.ch[parts[0]]; if(!ch) return;
      var c=null; for(var j=0;j<ch.list.length;j++) if(ch.list[j].id===parts[1]) c=ch.list[j];
      if(c) claimChallenge(parts[0],c);
    });
  }
}
function buildAvGrid(){
  var g=document.getElementById("avGrid"); if(!g) return;
  var html="";
  AVATARS.forEach(function(a){
    html+='<button class="avTile'+(a===profileAvatar()?" sel":"")+'" data-av="'+a+'">'+a+'</button>';
  });
  g.innerHTML=html;
}
function buildShop(){
  var box=document.getElementById("shopGrid"); if(!box) return;
  var html="";
  SHOP.forEach(function(it){
    var afford=store.diamonds>=it.price;
    html+='<div class="shopCard'+(afford?"":" poor")+'">'+
      '<div class="shopIco">'+it.ico+'</div>'+
      '<div class="shopName">'+it.n+'</div>'+
      '<div class="shopDesc">'+it.desc+'</div>'+
      '<button class="shopBuy" data-buy="'+it.id+'"'+(afford?"":" disabled")+'>'+it.price+' 💎</button>'+
      (it.id==="bomb"&&store.inv.bomb>0?'<div class="shopHave">'+T("owned",{0:store.inv.bomb})+'</div>':"")+
      '</div>';
  });
  box.innerHTML=html;
  var bs=box.querySelectorAll? box.querySelectorAll("[data-buy]") : [];
  for(var i=0;i<bs.length;i++){
    bs[i].addEventListener("click",function(){ buyItem(this.getAttribute("data-buy")); });
  }
  var packs=document.getElementById("packGrid");
  if(packs){
    var ph="";
    DIAMOND_PACKS.forEach(function(p){
      ph+='<div class="packCard"><div class="packAmt">💎 '+p.amt+'</div>'+
          (p.bonus?'<div class="packBonus">+'+p.bonus+'% '+T("bonus")+'</div>':"")+
          '<div class="packPrice">'+p.price+'</div>'+
          '<button class="packBuy" data-pack="'+p.id+'">'+T("demoBuy")+'</button></div>';
    });
    packs.innerHTML=ph;
    var pb=packs.querySelectorAll? packs.querySelectorAll("[data-pack]") : [];
    for(var j=0;j<pb.length;j++){
      pb[j].addEventListener("click",function(){ diaToast("💎 "+T("demoOnly"),""); });
    }
  }
}
function buildLeaderboard(){
  var box=document.getElementById("lbList"); if(!box) return;
  var which=document.getElementById("lbTabs").getAttribute("data-which")||"all";
  box.innerHTML='<div class="lbLoad">'+T("loading")+'</div>';
  lbFetch(which,function(rows){
    lbState.rows=rows.slice(0,LB_MAX);
    lbState.page=0;
    renderLbPage();
  });
}
var lbState={rows:[],page:0};
function renderLbPage(){
  var box=document.getElementById("lbList"); if(!box) return;
  var start=lbState.page*LB_PAGE;
  var slice=lbState.rows.slice(start,start+LB_PAGE);
  if(!slice.length){ box.innerHTML='<div class="lbLoad">'+T("noScores")+'</div>'; }
  else{
    var html="";
    slice.forEach(function(r,i){
      var rank=start+i+1;
      var medal = rank===1?"🥇": rank===2?"🥈": rank===3?"🥉": rank;
      html+='<div class="lbRow'+(r.me?" me":"")+'">'+
        '<div class="lbRank">'+medal+'</div>'+
        '<div class="lbName">'+String(r.name).slice(0,NAME_MAX)+'</div>'+
        '<div class="lbScore">'+r.score+'</div></div>';
    });
    box.innerHTML=html;
  }
  var up=document.getElementById("lbUp"), dn=document.getElementById("lbDown");
  if(up) up.disabled = lbState.page<=0;
  if(dn) dn.disabled = (lbState.page+1)*LB_PAGE >= lbState.rows.length;
  var info=document.getElementById("lbInfo");
  if(info) info.textContent=T("lbShowing",{0:Math.min(lbState.rows.length,(lbState.page+1)*LB_PAGE),1:lbState.rows.length});
}
function lbMove(dir){
  var maxPage=Math.max(0,Math.ceil(Math.min(lbState.rows.length,LB_MAX)/LB_PAGE)-1);
  lbState.page=Math.max(0,Math.min(maxPage,lbState.page+dir));
  renderLbPage();
}

/* ============================================================ wiring ====== */
/* Every economy screen is a peer now -- diamonds/Earn, shop, ranks,
   achievements. Opening one must close all the others, or two cards stack and
   the backdrop click lands on the wrong one. */
var PANELS=["diaOv","shopOv","rankOv","achOv","profOv","avatarOv","luckyOv"];
function openPanel(id){
  PANELS.forEach(function(p){
    if(p===id) return;
    var el=document.getElementById(p); if(el) el.classList.add("hide");
  });
  var t=document.getElementById(id); if(t) t.classList.remove("hide");
  refreshEcon();
  if(id==="diaOv") buildChallenges();
  if(id==="shopOv") buildShop();
  if(id==="rankOv"){
    if(document.getElementById("lbTabs")) document.getElementById("lbTabs").setAttribute("data-which","all");
    lbState.page=0; buildLeaderboard();
  }
  ac();
}
function wireEcon(){
  /* One screen per overlay, opened from home. Each gets the same three ways
     out: its ✕, a click on the dark backdrop, and opening another screen. */
  var diaPill=document.getElementById("diaPill");
  if(diaPill) diaPill.addEventListener("click",function(){ openPanel("diaOv"); });
  var sb=document.getElementById("shopBtnHome");
  if(sb) sb.addEventListener("click",function(){ openPanel("shopOv"); });
  var rb=document.getElementById("rankBtnHome");
  if(rb) rb.addEventListener("click",function(){ openPanel("rankOv"); });

  /* Every popup gets the same three ways out: its ✕, a backdrop tap, and
     opening another screen. profOv/avatarOv were missing from this list, which
     is exactly why their close buttons looked dead. */
  [["diaClose","diaOv"],["shopClose","shopOv"],["rankClose","rankOv"],
   ["profClose","profOv"],["avatarClose","avatarOv"]].forEach(function(pr){
    var x=document.getElementById(pr[0]);
    if(x) x.addEventListener("click",function(){
      var el=document.getElementById(pr[1]); if(el) el.classList.add("hide");
    });
    var ov=document.getElementById(pr[1]);
    if(ov) ov.addEventListener("click",function(e){ if(e.target===this) this.classList.add("hide"); });
  });

  var fb=document.getElementById("freeBtn");
  if(fb) fb.addEventListener("click",function(){ takeDailyFree(); });
  var ab=document.getElementById("adDiaBtn");
  if(ab) ab.addEventListener("click",function(){ requestReward(grantAdDiamonds); });

  var tabs=document.getElementById("lbTabs");
  if(tabs){
    ["all","weekly","daily"].forEach(function(w){
      var b=document.getElementById("lbTab_"+w);
      if(b) b.addEventListener("click",function(){
        ["all","weekly","daily"].forEach(function(x){
          var o=document.getElementById("lbTab_"+x); if(o) o.classList.toggle("on",x===w);
        });
        tabs.setAttribute("data-which",w);
        buildLeaderboard();
      });
    });
  }
  var lu=document.getElementById("lbUp"); if(lu) lu.addEventListener("click",function(){ lbMove(-1); });
  var ld=document.getElementById("lbDown"); if(ld) ld.addEventListener("click",function(){ lbMove(1); });

  var rn=document.getElementById("renameBtn");
  if(rn) rn.addEventListener("click",function(){
    if(!signedIn()){ diaToast("🔒","Login to change your name"); return; }
    var r=setName(prompt(T("namePrompt"),profileName()));
    if(r.ok) diaToast("👤 "+r.name,T("welcome"));
    else if(r.why==="cooldown") diaToast("⏳",T("renameIn",{0:r.days}));
    else if(r.why==="tooLong") diaToast("✂",T("tooLong",{0:r.max}));
    else diaToast("⚠",T("tooShort"));
    refreshEcon();
  });
  /* Home profile chip opens the profile popup; the face inside it opens the
     avatar picker. Both work for guests. */
  var pc=document.getElementById("profChip");
  if(pc) pc.addEventListener("click",function(){ openPanel("profOv"); });
  var pa=document.getElementById("profAvBtn");
  if(pa) pa.addEventListener("click",function(){ buildAvGrid(); openPanel("avatarOv"); });
  var ag=document.getElementById("avGrid");
  if(ag) ag.addEventListener("click",function(e){
    var t=e.target&&e.target.closest? e.target.closest(".avTile") : null;
    if(!t||!t.getAttribute("data-av")) return;
    store.profile.avatar=t.getAttribute("data-av"); save(); refreshEcon();
    buildAvGrid();
  });
  /* Sign-in invitation. Shown to guests only, once: dismissing it writes a
     flag so it never nags again, and signing in hides it for good. */
  var si=document.getElementById("signIn");
  if(si){
    var sg=document.getElementById("siGoogle");
    if(sg) sg.addEventListener("click",function(){
      Net.login("google",function(p){
        hideSignIn();
        diaToast("👤 "+profileName(),T("welcome"));
        openPanel("diaOv");
      });
    });
    var sl=document.getElementById("siLater");
    if(sl) sl.addEventListener("click",function(){
      store.siDismissed=true; save(); hideSignIn();
    });
  }
  var lo=document.getElementById("loginBtn");
  if(lo) lo.addEventListener("click",function(){
    Net.login("google",function(p){ diaToast("👤 "+profileName(),T("welcome")); openPanel("profOv"); });
  });
  /* The old reset button (which silently reverted the name to a default) was
     removed at the user's request -- nothing wires it now. */
}

/* ---------- 15e. home backdrop ---------- */
/* Painted orchard backdrops (portrait for handhelds, landscape for wide
   webviews), embedded as data URIs so the single-file build stays offline.
   Lives INSIDE the economy block so re-injecting economy.js never loses it. */
var BG_P="data:image/jpeg;base64,";
var BG_L="data:image/jpeg;base64,";
function applyHomeBg(){
  var el=document.getElementById("homeBg"); if(!el) return;
  el.style.backgroundImage = (innerHeight>innerWidth)? "url(\""+BG_P+"\")" : "url(\""+BG_L+"\")";
}
